import json, os
from safetensors import safe_open

model_dir = '/root/autodl-tmp/models/Qwen3-14B-Base'
with open(f'{model_dir}/model.safetensors.index.json') as f:
    index = json.load(f)

# Build reverse map: for each shard, get one representative key
shard_to_keys = {}
for key, shard in index['weight_map'].items():
    shard_to_keys.setdefault(shard, []).append(key)

# Pick one representative key per shard
shard_rep = {shard: keys[0] for shard, keys in shard_to_keys.items()}
print('Shard representatives:')
for s, k in sorted(shard_rep.items()):
    print(f'  {s}: {k}')

# Get hash files
known_non_shard = {'config.json', 'generation_config.json', 'merges.txt', 'model.safetensors.index.json', 'tokenizer.json', 'tokenizer_config.json', 'vocab.json'}
hash_files = sorted([f for f in os.listdir(model_dir) if f not in known_non_shard and not f.startswith('.')])
print(f'\nHash files ({len(hash_files)}): {hash_files}')

# For each hash file, check which shard it corresponds to
hash_to_shard = {}
for hf in hash_files:
    path = f'{model_dir}/{hf}'
    try:
        st = safe_open(path, framework='pt')
        keys = st.keys()
        for shard, rep_key in shard_rep.items():
            if rep_key in keys:
                hash_to_shard[hf] = shard
                break
    except Exception as e:
        print(f'  Error reading {hf}: {e}')

print('\nMapping:')
for hf, shard in sorted(hash_to_shard.items(), key=lambda x: x[1]):
    print(f'  {hf} -> {shard}')

# Create symlinks
created = 0
for hf, shard in hash_to_shard.items():
    dst = f'{model_dir}/{shard}'
    if not os.path.exists(dst):
        os.symlink(hf, dst)
        created += 1
        print(f'  LINKED: {hf} -> {shard}')
    else:
        print(f'  EXISTS: {shard}')
print(f'\nCreated {created} symlinks')
"
